<script setup lang="ts">
import {ref, watch} from 'vue';
import {api} from '../lib/api';
import {errorMessage} from '../lib/errors';
import {notify} from '../stores/notices';
import {date} from '../lib/content';
import type {CloudSave} from '../lib/types';
import LoadState from './LoadState.vue';
const props=defineProps<{accountId:string}>();
const saves=ref<CloudSave[]>([]), loading=ref(false), error=ref(''), editable=ref(false), editing=ref<CloudSave|null>(null), busy=ref(false), reason=ref(''), raw=ref('');
const values=ref({cash:0,total:0,swipes:0});
const url=()=>'/staff/users/'+props.accountId+'/games/rublemet/saves';
async function load(){loading.value=true;error.value='';try{const result=await api<{items:CloudSave[];editable:boolean}>(url(),{private:true});saves.value=result.items;editable.value=result.editable;}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
watch(()=>props.accountId,()=>{editing.value=null;void load()},{immediate:true});
function edit(save:CloudSave){editing.value=save;values.value={cash:save.payload.state.cash,total:save.payload.state.total,swipes:save.payload.state.swipes};raw.value=JSON.stringify(save.payload.state,null,2);reason.value='';}
async function save(){if(!editing.value)return;busy.value=true;try{const state=JSON.parse(raw.value);Object.assign(state,values.value);if(state.total<state.cash)throw new Error('Баланс не может превышать общий заработок.');const row=editing.value;await api(url()+'/'+row.slot,{private:true,method:'PUT',body:{reason:reason.value,save:{operation_id:crypto.randomUUID(),expected_revision:row.revision,schema_version:row.schema_version,payload:{...row.payload,state}}}});editing.value=null;await load();notify('Сохранение обновлено. Игра получит его при синхронизации.');}catch(e){notify(e instanceof SyntaxError?'В JSON есть ошибка.':e instanceof Error&&e.message==='Баланс не может превышать общий заработок.'?e.message:errorMessage(e),true)}finally{busy.value=false}}
</script>
<template><section class="player-saves"><div class="section-title"><h3>Сохранения Рублемёта</h3><button class="button secondary small" :disabled="loading||busy" @click="load">Обновить</button></div><p class="field-note">Данные из игры после входа в AGL ID. Слот 1 — текущий прогресс. Тестовый режим хранится отдельно.</p><LoadState :loading="loading" :error="error" @retry="load"><p v-if="!saves.length" class="quiet-state">Игра ещё не передала сохранение. Нужны вход в AGL ID и сборка с синхронизацией.</p><article v-for="row in saves" :key="row.slot" class="save-slot"><h4>Слот {{row.slot}} · версия {{row.revision}}</h4><p>Получено {{date(row.updated_at)}}</p><template v-if="row.payload.format==='rublemet/1'"><dl class="account-facts"><div><dt>Баланс</dt><dd>{{row.payload.state.cash.toLocaleString('ru-RU')}} ₽</dd></div><div><dt>Всего заработано</dt><dd>{{row.payload.state.total.toLocaleString('ru-RU')}} ₽</dd></div><div><dt>Взмахов</dt><dd>{{row.payload.state.swipes.toLocaleString('ru-RU')}}</dd></div></dl><button v-if="editable&&!editing" class="button secondary small" @click="edit(row)">Редактировать прогресс</button></template><p v-else class="muted">Сохранение прежнего формата. Автоматическое преобразование недоступно.</p></article></LoadState><form v-if="editing" class="form-stack inset-form" @submit.prevent="save"><h4>Изменение слота {{editing.slot}}</h4><label v-for="(label,key) in {cash:'Баланс, ₽',total:'Всего заработано, ₽',swipes:'Взмахов'}" :key="key">{{label}}<input v-model.number="values[key]" type="number" min="0" step="any" required/></label><details><summary>Остальной прогресс</summary><p class="field-note">JSON содержит профессии, бизнесы, сюжет и другие данные. Три поля выше сохраняются отдельно.</p><textarea v-model="raw" rows="12" spellcheck="false" aria-label="Данные сохранения" class="mono"/></details><label>Причина изменения<textarea v-model="reason" minlength="3" maxlength="500" required rows="2"/></label><div class="button-row"><button class="button" :disabled="busy">Сохранить</button><button type="button" class="button secondary" :disabled="busy" @click="editing=null">Отмена</button></div><p class="field-note">Если игра успеет записать новую версию, сайт попросит обновить сохранение. Правка не перезапишет её молча.</p></form></section></template>
